  public static String retryConfigToYaml(Httpclient.RetryConfig msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "RetryConfig is null");
    }
    try {
      String json = retryConfigToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      Yaml yaml = new Yaml();
      return yaml.dump(map);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to serialize RetryConfig to YAML: " + e.getMessage(), e);
    }
  }

  public static Httpclient.RetryConfig retryConfigFromYaml(String yamlStr) throws ProtoException {
    if (yamlStr == null || yamlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "yamlStr is null or empty");
    }
    try {
      Yaml yaml = new Yaml();
      @SuppressWarnings("unchecked")
      Map<String, Object> map = (Map<String, Object>) yaml.load(yamlStr);
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return retryConfigFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse RetryConfig from YAML: " + e.getMessage(), e);
    }
  }

  public static String retryConfigToToml(Httpclient.RetryConfig msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "RetryConfig is null");
    }
    try {
      String json = retryConfigToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      StringBuilder toml = new StringBuilder();
      if (map == null || map.isEmpty()) {
        return "# Empty RetryConfig\n";
      }
      for (Map.Entry<String, Object> entry : map.entrySet()) {
        toml.append(entry.getKey()).append(" = ");
        if (entry.getValue() instanceof String) {
          toml.append("\"").append(entry.getValue()).append("\"");
        } else {
          toml.append(entry.getValue());
        }
        toml.append("\n");
      }
      return toml.toString();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to serialize RetryConfig to TOML: " + e.getMessage(), e);
    }
  }

  public static Httpclient.RetryConfig retryConfigFromToml(String tomlStr) throws ProtoException {
    if (tomlStr == null || tomlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "tomlStr is null or empty");
    }
    try {
      Toml toml = new Toml().read(tomlStr);
      Map<String, Object> map = toml.toMap();
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return retryConfigFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse RetryConfig from TOML: " + e.getMessage(), e);
    }
  }

  // ============ Validation ============
  public static void validateHttpClientConfig(Httpclient.HttpClientConfig msg)
      throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate timeoutSeconds (assert_duration: NON_NEGATIVE)
    if (msg.getTimeoutSeconds() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field timeoutSeconds must be non-negative (>= 0), got: %d",
              msg.getTimeoutSeconds()));
    }
    // Validate maxIdleConns (assert_ge: 0)
    if (msg.getMaxIdleConns() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxIdleConns must be >= 0, got: %s", msg.getMaxIdleConns()));
    }
    // Validate maxIdleConnsPerHost (assert_ge: 0)
    if (msg.getMaxIdleConnsPerHost() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field maxIdleConnsPerHost must be >= 0, got: %s", msg.getMaxIdleConnsPerHost()));
    }
    // Validate idleConnTimeoutSeconds (assert_duration: NON_NEGATIVE)
    if (msg.getIdleConnTimeoutSeconds() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field idleConnTimeoutSeconds must be non-negative (>= 0), got: %d",
              msg.getIdleConnTimeoutSeconds()));
    }
    // Validate tlsHandshakeTimeoutSeconds (assert_duration: NON_NEGATIVE)
    if (msg.getTlsHandshakeTimeoutSeconds() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field tlsHandshakeTimeoutSeconds must be non-negative (>= 0), got: %d",
              msg.getTlsHandshakeTimeoutSeconds()));
    }
    // Validate expectContinueTimeoutSeconds (assert_duration: NON_NEGATIVE)
    if (msg.getExpectContinueTimeoutSeconds() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field expectContinueTimeoutSeconds must be non-negative (>= 0), got: %d",
              msg.getExpectContinueTimeoutSeconds()));
    }
    // Validate responseHeaderTimeoutSeconds (assert_duration: NON_NEGATIVE)
    if (msg.getResponseHeaderTimeoutSeconds() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field responseHeaderTimeoutSeconds must be non-negative (>= 0), got: %d",
              msg.getResponseHeaderTimeoutSeconds()));
    }
  }

  public static void validateRetryConfig(Httpclient.RetryConfig msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate maxRetries (assert_ge: 0)
    if (msg.getMaxRetries() < 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxRetries must be >= 0, got: %s", msg.getMaxRetries()));
    }
    // Validate maxRetries (assert_le: 10)
    if (msg.getMaxRetries() > 10) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxRetries must be <= 10, got: %s", msg.getMaxRetries()));
    }
    // Validate initialBackoffMs (assert_duration: POSITIVE)
    if (msg.getInitialBackoffMs() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field initialBackoffMs must be positive (> 0), got: %d", msg.getInitialBackoffMs()));
    }
    // Validate maxBackoffMs (assert_duration: POSITIVE)
    if (msg.getMaxBackoffMs() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field maxBackoffMs must be positive (> 0), got: %d", msg.getMaxBackoffMs()));
    }
    // Validate backoffMultiplier (assert_gt: 0)
    if (msg.getBackoffMultiplier() <= 0) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field backoffMultiplier must be > 0, got: %s", msg.getBackoffMultiplier()));
    }
  }

  // ============ Merge ============
  public static Httpclient.HttpClientConfig.Builder mergeHttpClientConfig(
      Httpclient.HttpClientConfig dst, Httpclient.HttpClientConfig src) {
    Httpclient.HttpClientConfig.Builder builder = dst.toBuilder();
    if (!dst.getInsecureSkipVerify()) {
      builder.setInsecureSkipVerify(src.getInsecureSkipVerify());
    }
    if (!dst.getDisableKeepAlives()) {
      builder.setDisableKeepAlives(src.getDisableKeepAlives());
    }
    if (dst.getRootCertsList().isEmpty()) {
      builder.addAllRootCerts(src.getRootCertsList());
    }
    if (!dst.hasClientCert() && src.hasClientCert()) {
      builder.setClientCert(src.getClientCert());
    }
    if (dst.getTimeoutSeconds() == 0) {
      builder.setTimeoutSeconds(src.getTimeoutSeconds());
    }
    if (dst.getMaxIdleConns() == 0) {
      builder.setMaxIdleConns(src.getMaxIdleConns());
    }
    if (dst.getMaxIdleConnsPerHost() == 0) {
      builder.setMaxIdleConnsPerHost(src.getMaxIdleConnsPerHost());
    }
    if (dst.getIdleConnTimeoutSeconds() == 0) {
      builder.setIdleConnTimeoutSeconds(src.getIdleConnTimeoutSeconds());
    }
    if (dst.getTlsHandshakeTimeoutSeconds() == 0) {
      builder.setTlsHandshakeTimeoutSeconds(src.getTlsHandshakeTimeoutSeconds());
    }
    if (dst.getExpectContinueTimeoutSeconds() == 0) {
      builder.setExpectContinueTimeoutSeconds(src.getExpectContinueTimeoutSeconds());
    }
    if (dst.getResponseHeaderTimeoutSeconds() == 0) {
      builder.setResponseHeaderTimeoutSeconds(src.getResponseHeaderTimeoutSeconds());
    }
    if (!dst.hasRetryConfig() && src.hasRetryConfig()) {
      builder.setRetryConfig(src.getRetryConfig());
    } else if (dst.hasRetryConfig() && src.hasRetryConfig()) {
      builder.setRetryConfig(mergeRetryConfig(dst.getRetryConfig(), src.getRetryConfig()).build());
    }
    if (!dst.getDisableValidation()) {
      builder.setDisableValidation(src.getDisableValidation());
    }
    return builder;
  }

  public static Httpclient.RetryConfig.Builder mergeRetryConfig(
      Httpclient.RetryConfig dst, Httpclient.RetryConfig src) {
    Httpclient.RetryConfig.Builder builder = dst.toBuilder();
    if (dst.getMaxRetries() == 0) {
      builder.setMaxRetries(src.getMaxRetries());
    }
    if (dst.getInitialBackoffMs() == 0) {
      builder.setInitialBackoffMs(src.getInitialBackoffMs());
    }
    if (dst.getMaxBackoffMs() == 0) {
      builder.setMaxBackoffMs(src.getMaxBackoffMs());
    }
    if (dst.getBackoffMultiplier() == 0.0) {
      builder.setBackoffMultiplier(src.getBackoffMultiplier());
    }
    if (dst.getRetryableStatusCodesList().isEmpty()) {
      builder.addAllRetryableStatusCodes(src.getRetryableStatusCodesList());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> httpClientConfigToEnvVar(Httpclient.HttpClientConfig msg) {
    Map<String, String> result = new HashMap<>();
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_INSECURE_SKIP_VERIFY",
        String.valueOf(msg.getInsecureSkipVerify()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_DISABLE_KEEP_ALIVES", String.valueOf(msg.getDisableKeepAlives()));
    if (msg.hasClientCert()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.x509.Helpers
              .x509CertChainToEnvVar(msg.getClientCert()));
    }
    result.put("PROTO_HTTP_CLIENT_CONFIG_TIMEOUT_SECONDS", String.valueOf(msg.getTimeoutSeconds()));
    result.put("PROTO_HTTP_CLIENT_CONFIG_MAX_IDLE_CONNS", String.valueOf(msg.getMaxIdleConns()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_MAX_IDLE_CONNS_PER_HOST",
        String.valueOf(msg.getMaxIdleConnsPerHost()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_IDLE_CONN_TIMEOUT_SECONDS",
        String.valueOf(msg.getIdleConnTimeoutSeconds()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_TLS_HANDSHAKE_TIMEOUT_SECONDS",
        String.valueOf(msg.getTlsHandshakeTimeoutSeconds()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_EXPECT_CONTINUE_TIMEOUT_SECONDS",
        String.valueOf(msg.getExpectContinueTimeoutSeconds()));
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_RESPONSE_HEADER_TIMEOUT_SECONDS",
        String.valueOf(msg.getResponseHeaderTimeoutSeconds()));
    if (msg.hasRetryConfig()) {
      result.putAll(retryConfigToEnvVar(msg.getRetryConfig()));
    }
    result.put(
        "PROTO_HTTP_CLIENT_CONFIG_DISABLE_VALIDATION", String.valueOf(msg.getDisableValidation()));
    return result;
  }

  public static Httpclient.HttpClientConfig.Builder httpClientConfigFromEnvVar(
      Map<String, String> env) {
    Httpclient.HttpClientConfig.Builder builder = Httpclient.HttpClientConfig.newBuilder();
    String val;
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_INSECURE_SKIP_VERIFY");
    if (val != null && !val.isEmpty()) {
      builder.setInsecureSkipVerify(Boolean.parseBoolean(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_DISABLE_KEEP_ALIVES");
    if (val != null && !val.isEmpty()) {
      builder.setDisableKeepAlives(Boolean.parseBoolean(val));
    }
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.x509.Helpers
              .x509CertChainFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setClientCert(sub);
      }
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setTimeoutSeconds(Long.parseLong(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_MAX_IDLE_CONNS");
    if (val != null && !val.isEmpty()) {
      builder.setMaxIdleConns(Integer.parseInt(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_MAX_IDLE_CONNS_PER_HOST");
    if (val != null && !val.isEmpty()) {
      builder.setMaxIdleConnsPerHost(Integer.parseInt(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_IDLE_CONN_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setIdleConnTimeoutSeconds(Long.parseLong(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_TLS_HANDSHAKE_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setTlsHandshakeTimeoutSeconds(Long.parseLong(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_EXPECT_CONTINUE_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setExpectContinueTimeoutSeconds(Long.parseLong(val));
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_RESPONSE_HEADER_TIMEOUT_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setResponseHeaderTimeoutSeconds(Long.parseLong(val));
    }
    {
      var sub = retryConfigFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setRetryConfig(sub);
      }
    }
    val = env.get("PROTO_HTTP_CLIENT_CONFIG_DISABLE_VALIDATION");
    if (val != null && !val.isEmpty()) {
      builder.setDisableValidation(Boolean.parseBoolean(val));
    }
    return builder;
  }

  public static Map<String, String> retryConfigToEnvVar(Httpclient.RetryConfig msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_RETRY_CONFIG_MAX_RETRIES", String.valueOf(msg.getMaxRetries()));
    result.put("PROTO_RETRY_CONFIG_INITIAL_BACKOFF_MS", String.valueOf(msg.getInitialBackoffMs()));
    result.put("PROTO_RETRY_CONFIG_MAX_BACKOFF_MS", String.valueOf(msg.getMaxBackoffMs()));
    result.put("PROTO_RETRY_CONFIG_BACKOFF_MULTIPLIER", String.valueOf(msg.getBackoffMultiplier()));
    if (!msg.getRetryableStatusCodesList().isEmpty()) {
      result.put(
          "PROTO_RETRY_CONFIG_RETRYABLE_STATUS_CODES",
          msg.getRetryableStatusCodesList().stream()
              .map(String::valueOf)
              .collect(Collectors.joining(",")));
    }
    return result;
  }

  public static Httpclient.RetryConfig.Builder retryConfigFromEnvVar(Map<String, String> env) {
    Httpclient.RetryConfig.Builder builder = Httpclient.RetryConfig.newBuilder();
    String val;
    val = env.get("PROTO_RETRY_CONFIG_MAX_RETRIES");
    if (val != null && !val.isEmpty()) {
      builder.setMaxRetries(Integer.parseInt(val));
    }
    val = env.get("PROTO_RETRY_CONFIG_INITIAL_BACKOFF_MS");
    if (val != null && !val.isEmpty()) {
      builder.setInitialBackoffMs(Long.parseLong(val));
    }
    val = env.get("PROTO_RETRY_CONFIG_MAX_BACKOFF_MS");
    if (val != null && !val.isEmpty()) {
      builder.setMaxBackoffMs(Long.parseLong(val));
    }
    val = env.get("PROTO_RETRY_CONFIG_BACKOFF_MULTIPLIER");
    if (val != null && !val.isEmpty()) {
      builder.setBackoffMultiplier(Double.parseDouble(val));
    }
    val = env.get("PROTO_RETRY_CONFIG_RETRYABLE_STATUS_CODES");
    if (val != null && !val.isEmpty()) {
      builder.addAllRetryableStatusCodes(
          Arrays.stream(val.split(","))
              .map(String::trim)
              .map(Integer::parseInt)
              .collect(Collectors.toList()));
    }
    return builder;
  }
